export function getCharactersByOrder(count: number = 50): CharacterData[] {
  return getCommonFirst().slice(0, count)
}

// 幼小衔接常用汉字优先顺序（前150字）
const COMMON_FIRST = '一二三四五六七八九十人大小上下天地日月水火山石田土木禾花草虫鱼鸟马牛羊云雨风电门户口目耳手足坐立走来去出入开关多少高低长短方圆白黑红绿好坏美丑男女老少爸妈哥姐妹弟你我他们的了是有不在会能以要就也都很大最前后左右里外东西南北中正反明暗新旧快慢轻重远近冷暖热凉甜苦香臭干湿软硬粗细厚薄宽窄对错问答说听读写看想吃喝笑哭唱跳跑走飞游爬站立睡醒开关进出给接送买回用玩做学习练习考试东西书包笔纸本课桌椅子窗灯钟表衣帽鞋袜饭菜肉面汤果奶糖蛋饼茶酒烟药针医院床被枕'

export function getCommonFirst(): CharacterData[] {
  const charMap = new Map(CHARACTERS.map(c => [c.char, c]))
  const prioritized: CharacterData[] = []
  const usedChars = new Set<string>()

  for (const ch of COMMON_FIRST) {
    const data = charMap.get(ch)
    if (data && !usedChars.has(data.id)) {
      prioritized.push(data)
      usedChars.add(data.id)
    }
  }

  // 追加剩余字符
  for (const c of CHARACTERS) {
    if (!usedChars.has(c.id)) {
      prioritized.push(c)
      usedChars.add(c.id)
    }
  }

  return prioritized
}

export function getCharacterById(id: string): CharacterData | undefined {
  return CHARACTERS.find(c => c.id === id)
}

export function getCharacterByChar(char: string): CharacterData | undefined {
  return CHARACTERS.find(c => c.char === char)
}

export function getDistractors(targetId: string, count: number = 3): CharacterData[] {
  const others = CHARACTERS.filter(c => c.id !== targetId)
  const shuffled = [...others].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, count)
}
